(() => {
  (typeof ngDevMode === "undefined" || ngDevMode) && setClassMetadata(OrderDetailComponent, [{
    type: Component,
    args: [{ standalone: false, selector: "app-order-detail", template: `<!-- order-detail.component.html -->\r
<div class="min-h-screen bg-gradient-to-br from-gray-900 to-black pt-24 px-4 pb-12">\r
  <div class="max-w-7xl mx-auto">\r
\r
    <!-- Loading -->\r
    <div *ngIf="isLoading" class="flex items-center justify-center py-20">\r
      <div class="text-center">\r
        <div class="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-500 mx-auto mb-4"></div>\r
        <p class="text-gray-400">Cargando detalles de la orden...</p>\r
      </div>\r
    </div>\r
\r
    <!-- Error -->\r
    <div *ngIf="error && !isLoading" class="bg-red-900/40 border border-red-500/40 rounded-xl p-6 text-center">\r
      <p class="text-red-300 mb-4">{{ error }}</p>\r
      <button (click)="cargarDetalle()" class="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition">\r
        Reintentar\r
      </button>\r
    </div>\r
\r
    <!-- Contenido Principal -->\r
    <ng-container *ngIf="!isLoading && orden">\r
      \r
      <!-- Header -->\r
      <div class="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">\r
        <div>\r
          <div class="flex items-center gap-3 mb-2">\r
            <button routerLink="/orders" class="text-gray-400 hover:text-white transition">\r
              <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"/>\r
              </svg>\r
            </button>\r
            <h1 class="text-3xl md:text-4xl font-bold text-white">\r
              Orden #{{ orden.codigo_orden }}\r
            </h1>\r
<span [class]="'px-3 py-1 rounded-full text-xs font-medium ' + getEstadoClase(orden.estado_orden)">\r
  {{ getEstadoLabel(orden.estado_orden) }}\r
</span>\r
          </div>\r
          <p class="text-gray-400">Creada el {{ orden.fecha_creacion | date:'longDate' }}</p>\r
        </div>\r
        \r
        <!-- Acciones r\xE1pidas -->\r
        <div class="flex gap-3 flex-wrap">\r
          <button (click)="showNotificarModal = true" \r
                  class="flex items-center gap-2 px-4 py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition">\r
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/>\r
            </svg>\r
            Notificar Cliente\r
          </button>\r
          <button (click)="showPagoModal = true" \r
                  class="flex items-center gap-2 px-4 py-2.5 bg-green-600 text-white rounded-lg hover:bg-green-700 transition">\r
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
              <line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>\r
            </svg>\r
            Registrar Pago\r
          </button>\r
        </div>\r
      </div>\r
\r
      <!-- Tabs de Navegaci\xF3n -->\r
      <div class="flex gap-1 mb-8 bg-gray-800/50 rounded-xl p-1.5 overflow-x-auto">\r
        <button *ngFor="let tab of tabs" \r
                (click)="activeTab = tab.id"\r
                [class]="'flex items-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium transition-all whitespace-nowrap ' +\r
                        (activeTab === tab.id ? 'bg-orange-600 text-white shadow-lg' : 'text-gray-400 hover:text-white hover:bg-gray-700/50')">\r
          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" [innerHTML]="tab.icon"></svg>\r
          {{ tab.label }}\r
        </button>\r
      </div>\r
\r
      <!-- Contenido de Tabs -->\r
      <div class="space-y-6">\r
\r
        <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
        <!-- TAB: INFORMACI\xD3N GENERAL -->\r
        <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
        <div *ngIf="activeTab === 'info'" class="grid grid-cols-1 lg:grid-cols-2 gap-6">\r
          \r
          <!-- Tarjeta: Cliente -->\r
          <div class="bg-gray-800/50 backdrop-blur-sm rounded-2xl border border-gray-700 p-6">\r
            <div class="flex items-center gap-3 mb-6">\r
              <div class="bg-blue-600/20 p-2.5 rounded-lg">\r
                <svg class="w-5 h-5 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                  <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>\r
                </svg>\r
              </div>\r
              <h3 class="text-lg font-bold text-white">Informaci\xF3n del Cliente</h3>\r
            </div>\r
            <div class="space-y-3" *ngIf="orden.cliente_info; else noCliente">\r
              <div class="flex justify-between py-2 border-b border-gray-700/50">\r
                <span class="text-gray-400 text-sm">Nombre</span>\r
                <span class="text-white font-medium">{{ orden.cliente_info.nombre }}</span>\r
              </div>\r
              <div class="flex justify-between py-2 border-b border-gray-700/50">\r
                <span class="text-gray-400 text-sm">Identificaci\xF3n</span>\r
                <span class="text-white">{{ orden.cliente_info.identificacion }}</span>\r
              </div>\r
              <div class="flex justify-between py-2 border-b border-gray-700/50">\r
                <span class="text-gray-400 text-sm">Email</span>\r
                <span class="text-blue-400">{{ orden.cliente_info.email }}</span>\r
              </div>\r
              <div class="flex justify-between py-2 border-b border-gray-700/50">\r
                <span class="text-gray-400 text-sm">Tel\xE9fono</span>\r
                <span class="text-white">{{ orden.cliente_info.telefono_1 }}</span>\r
              </div>\r
              <div class="flex justify-between py-2">\r
                <span class="text-gray-400 text-sm">Direcci\xF3n</span>\r
                <span class="text-white text-right max-w-[200px]">{{ orden.cliente_info.direccion }}</span>\r
              </div>\r
            </div>\r
            <ng-template #noCliente>\r
              <p class="text-gray-500 text-center py-4">Informaci\xF3n no disponible</p>\r
            </ng-template>\r
          </div>\r
\r
          <!-- Tarjeta: Vendedor -->\r
          <div class="bg-gray-800/50 backdrop-blur-sm rounded-2xl border border-gray-700 p-6">\r
            <div class="flex items-center gap-3 mb-6">\r
              <div class="bg-purple-600/20 p-2.5 rounded-lg">\r
                <svg class="w-5 h-5 text-purple-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                  <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/>\r
                  <path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>\r
                </svg>\r
              </div>\r
              <h3 class="text-lg font-bold text-white">Vendedor Asignado</h3>\r
            </div>\r
            <div class="space-y-3" *ngIf="orden.vendedor_info; else noVendedor">\r
              <div class="flex justify-between py-2 border-b border-gray-700/50">\r
                <span class="text-gray-400 text-sm">Nombre</span>\r
                <span class="text-white font-medium">{{ orden.vendedor_info.nombre }}</span>\r
              </div>\r
              <div class="flex justify-between py-2 border-b border-gray-700/50">\r
                <span class="text-gray-400 text-sm">Identificaci\xF3n</span>\r
                <span class="text-white">{{ orden.vendedor_info.identificacion }}</span>\r
              </div>\r
              <div class="flex justify-between py-2 border-b border-gray-700/50">\r
                <span class="text-gray-400 text-sm">Email</span>\r
                <span class="text-purple-400">{{ orden.vendedor_info.email }}</span>\r
              </div>\r
              <div class="flex justify-between py-2">\r
                <span class="text-gray-400 text-sm">Tel\xE9fono</span>\r
                <span class="text-white">{{ orden.vendedor_info.telefono }}</span>\r
              </div>\r
            </div>\r
            <ng-template #noVendedor>\r
              <p class="text-gray-500 text-center py-4">Informaci\xF3n no disponible</p>\r
            </ng-template>\r
          </div>\r
\r
          <!-- Tarjeta: Veh\xEDculo -->\r
          <div class="bg-gray-800/50 backdrop-blur-sm rounded-2xl border border-gray-700 p-6 lg:col-span-2">\r
            <div class="flex items-center gap-3 mb-6">\r
              <div class="bg-orange-600/20 p-2.5 rounded-lg">\r
                <svg class="w-5 h-5 text-orange-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                  <rect x="1" y="3" width="15" height="13"/><polygon points="16 8 20 8 23 11 23 16 16 16 16 8"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/>\r
                </svg>\r
              </div>\r
              <h3 class="text-lg font-bold text-white">Veh\xEDculo</h3>\r
            </div>\r
            <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4" *ngIf="orden.vehiculo_info; else noVehiculo">\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">Marca / Modelo</p>\r
                <p class="text-white font-medium">{{ orden.vehiculo_info.modelo?.marca }} {{ orden.vehiculo_info.modelo?.nombre }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">Versi\xF3n</p>\r
                <p class="text-white font-medium">{{ orden.vehiculo_info.version?.nombre }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">A\xF1o</p>\r
                <p class="text-white font-medium">{{ orden.vehiculo_info.version?.['a\xF1o_modelo'] }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">Motorizaci\xF3n</p>\r
                <p class="text-white">{{ orden.vehiculo_info.version?.motorizacion }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">Transmisi\xF3n</p>\r
                <p class="text-white">{{ orden.vehiculo_info.version?.transmision }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">VIN</p>\r
                <p class="text-white font-mono text-sm">{{ orden.vehiculo_info.vin }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">Color Exterior</p>\r
                <div class="flex items-center gap-2">\r
                  <span class="w-4 h-4 rounded-full border border-gray-500" [style.background-color]="orden.vehiculo_info.color_exterior"></span>\r
                  <span class="text-white">{{ orden.vehiculo_info.color_exterior }}</span>\r
                </div>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">N\xB0 Motor</p>\r
                <p class="text-white font-mono text-sm">{{ orden.vehiculo_info.numero_motor }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">Ubicaci\xF3n</p>\r
                <p class="text-white">{{ orden.vehiculo_info.ubicacion }}</p>\r
              </div>\r
            </div>\r
            <ng-template #noVehiculo>\r
              <p class="text-gray-500 text-center py-4">Informaci\xF3n no disponible</p>\r
            </ng-template>\r
          </div>\r
\r
          <!-- Tarjeta: Transacci\xF3n -->\r
          <div class="bg-gray-800/50 backdrop-blur-sm rounded-2xl border border-gray-700 p-6 lg:col-span-2" *ngIf="orden.transaccion">\r
            <div class="flex items-center justify-between mb-6">\r
              <div class="flex items-center gap-3">\r
                <div class="bg-green-600/20 p-2.5 rounded-lg">\r
                  <svg class="w-5 h-5 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                    <line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>\r
                  </svg>\r
                </div>\r
                <h3 class="text-lg font-bold text-white">Transacci\xF3n de Pago</h3>\r
              </div>\r
              <span [class]="'px-3 py-1 rounded-full text-xs font-medium border ' + \r
                (orden.transaccion.estado_pago_nombre === 'Pagado' ? 'bg-green-900/40 text-green-300 border-green-700/40' : \r
                 orden.transaccion.estado_pago_nombre === 'Pendiente' ? 'bg-yellow-900/40 text-yellow-300 border-yellow-700/40' : \r
                 'bg-gray-800 text-gray-400 border-gray-700')">\r
                {{ orden.transaccion.estado_pago_nombre }}\r
              </span>\r
            </div>\r
\r
            <!-- Resumen Financiero -->\r
            <div class="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">\r
              <div class="bg-gray-900/80 rounded-xl p-5 text-center">\r
                <p class="text-gray-500 text-xs uppercase tracking-wider mb-2">Monto Total</p>\r
                <p class="text-3xl font-bold text-green-400">{{ orden.transaccion.monto_total | currency:orden.transaccion.moneda }}</p>\r
              </div>\r
              <div class="bg-gray-900/80 rounded-xl p-5 text-center">\r
                <p class="text-gray-500 text-xs uppercase tracking-wider mb-2">Monto Inicial</p>\r
                <p class="text-3xl font-bold text-blue-400">{{ orden.transaccion.monto_inicial | currency:orden.transaccion.moneda }}</p>\r
              </div>\r
              <div class="bg-gray-900/80 rounded-xl p-5 text-center">\r
                <p class="text-gray-500 text-xs uppercase tracking-wider mb-2">Saldo Restante</p>\r
                <p [class]="'text-3xl font-bold ' + getMontoRestanteClass()">\r
                  {{ orden.transaccion.monto_restante | currency:orden.transaccion.moneda }}\r
                </p>\r
              </div>\r
            </div>\r
\r
            <!-- Barra de Progreso -->\r
            <div class="mb-6">\r
              <div class="flex justify-between text-sm mb-2">\r
                <span class="text-gray-400">Progreso de Pago</span>\r
                <span class="text-white font-medium">{{ orden.transaccion.porcentaje_pagado }}%</span>\r
              </div>\r
              <div class="w-full bg-gray-700 rounded-full h-3 overflow-hidden">\r
                <div class="bg-gradient-to-r from-green-500 to-green-400 h-3 rounded-full transition-all duration-500" \r
                     [style.width]="orden.transaccion.porcentaje_pagado + '%'"></div>\r
              </div>\r
            </div>\r
\r
            <!-- Detalles del Pago -->\r
            <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">M\xE9todo de Pago</p>\r
                <p class="text-white font-medium">{{ orden.transaccion.metodo_pago_nombre }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">Referencia</p>\r
                <p class="text-white font-mono text-sm">{{ orden.transaccion.referencia }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">Moneda</p>\r
                <p class="text-white">{{ orden.transaccion.moneda }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3">\r
                <p class="text-gray-500 text-xs mb-1">Fecha de Pago</p>\r
                <p class="text-white">{{ orden.transaccion.fecha_pago | date:'mediumDate' }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3" *ngIf="orden.transaccion.entidad_financiera_nombre">\r
                <p class="text-gray-500 text-xs mb-1">Entidad Financiera</p>\r
                <p class="text-white">{{ orden.transaccion.entidad_financiera_nombre }}</p>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-3" *ngIf="orden.transaccion.tasa_cambio">\r
                <p class="text-gray-500 text-xs mb-1">Tasa de Cambio</p>\r
                <p class="text-white">{{ orden.transaccion.tasa_cambio }}</p>\r
              </div>\r
            </div>\r
          </div>\r
\r
        </div>\r
\r
        <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
        <!-- TAB: PAGOS PARCIALES -->\r
        <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
        <div *ngIf="activeTab === 'pagos'" class="space-y-6">\r
          \r
          <div class="flex justify-between items-center">\r
            <h3 class="text-xl font-bold text-white">Pagos Registrados</h3>\r
            <button (click)="showPagoModal = true" \r
                    class="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition">\r
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/>\r
              </svg>\r
              Nuevo Pago\r
            </button>\r
          </div>\r
\r
          <!-- Resumen de Cuotas -->\r
          <div class="grid grid-cols-1 md:grid-cols-3 gap-4" *ngIf="orden.pagos_parciales.length > 0">\r
            <div class="bg-gray-800/50 rounded-xl p-4 border border-gray-700">\r
              <p class="text-gray-500 text-xs mb-1">Total Cuotas</p>\r
              <p class="text-2xl font-bold text-white">{{ orden.pagos_parciales.length }}</p>\r
            </div>\r
            <div class="bg-gray-800/50 rounded-xl p-4 border border-gray-700">\r
              <p class="text-gray-500 text-xs mb-1">Total Pagado</p>\r
              <p class="text-2xl font-bold text-green-400">{{ totalPagado | currency:orden.transaccion?.moneda }}</p>\r
            </div>\r
            <div class="bg-gray-800/50 rounded-xl p-4 border border-gray-700">\r
              <p class="text-gray-500 text-xs mb-1">Cuotas Pendientes</p>\r
              <p class="text-2xl font-bold text-yellow-400">{{ cuotasPendientes }}</p>\r
            </div>\r
          </div>\r
\r
          <!-- Tabla de Pagos -->\r
          <div class="bg-gray-800/50 backdrop-blur-sm rounded-2xl border border-gray-700 overflow-hidden">\r
            <div class="overflow-x-auto">\r
              <table class="w-full" *ngIf="orden.pagos_parciales.length > 0; else sinPagos">\r
                <thead class="bg-gray-900/50">\r
                  <tr>\r
                    <th class="text-left p-4 text-xs font-medium text-gray-500 uppercase">Cuota</th>\r
                    <th class="text-left p-4 text-xs font-medium text-gray-500 uppercase">Monto</th>\r
                    <th class="text-left p-4 text-xs font-medium text-gray-500 uppercase">Fecha Pago</th>\r
                    <th class="text-left p-4 text-xs font-medium text-gray-500 uppercase">Vencimiento</th>\r
                    <th class="text-left p-4 text-xs font-medium text-gray-500 uppercase">Estado</th>\r
                    <th class="text-left p-4 text-xs font-medium text-gray-500 uppercase">Comprobante</th>\r
                    <th class="text-left p-4 text-xs font-medium text-gray-500 uppercase">Notas</th>\r
                  </tr>\r
                </thead>\r
                <tbody>\r
                  <tr *ngFor="let pago of orden.pagos_parciales" class="border-t border-gray-700/60 hover:bg-gray-900/40">\r
                    <td class="p-4">\r
                      <span class="text-white font-bold">#{{ pago.numero_cuota }}</span>\r
                    </td>\r
                    <td class="p-4">\r
                      <span class="text-green-400 font-medium">{{ pago.monto_pagado | currency }}</span>\r
                    </td>\r
                    <td class="p-4">\r
                      <span class="text-gray-300">{{ pago.fecha_pago | date:'mediumDate' }}</span>\r
                    </td>\r
                    <td class="p-4">\r
                      <span class="text-gray-400">{{ pago.fecha_vencimiento ? (pago.fecha_vencimiento | date:'mediumDate') : '\u2014' }}</span>\r
                    </td>\r
                    <td class="p-4">\r
                      <span [class]="'px-2 py-1 rounded-full text-xs font-medium ' + \r
                        (pago.estado_nombre === 'Pagado' ? 'bg-green-900/40 text-green-300' : 'bg-yellow-900/40 text-yellow-300')">\r
                        {{ pago.estado_nombre }}\r
                      </span>\r
                    </td>\r
                    <td class="p-4">\r
                      <a *ngIf="pago.comprobante_url" [href]="pago.comprobante_url" target="_blank" \r
                         class="text-blue-400 hover:text-blue-300 underline text-sm flex items-center gap-1">\r
                        <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"/>\r
                        </svg>\r
                        Ver\r
                      </a>\r
                      <span *ngIf="!pago.comprobante_url" class="text-gray-500 text-sm">\u2014</span>\r
                    </td>\r
                    <td class="p-4">\r
                      <span class="text-gray-400 text-sm max-w-[150px] truncate block">{{ pago.notas || '\u2014' }}</span>\r
                    </td>\r
                  </tr>\r
                </tbody>\r
              </table>\r
              <ng-template #sinPagos>\r
                <div class="text-center py-12">\r
                  <svg class="w-12 h-12 text-gray-600 mx-auto mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                    <line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>\r
                  </svg>\r
                  <p class="text-gray-500">No hay pagos registrados a\xFAn</p>\r
                </div>\r
              </ng-template>\r
            </div>\r
          </div>\r
        </div>\r
\r
        <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
        <!-- TAB: NOTIFICACIONES -->\r
        <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
        <div *ngIf="activeTab === 'notificaciones'" class="space-y-6">\r
          \r
          <div class="flex justify-between items-center">\r
            <h3 class="text-xl font-bold text-white">Historial de Notificaciones</h3>\r
            <button (click)="showNotificarModal = true" \r
                    class="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition">\r
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/>\r
              </svg>\r
              Nueva Notificaci\xF3n\r
            </button>\r
          </div>\r
\r
          <!-- Lista de Notificaciones -->\r
          <div class="space-y-3" *ngIf="orden.notificaciones.length > 0; else sinNotificaciones">\r
            <div *ngFor="let notif of orden.notificaciones" \r
                 class="bg-gray-800/50 backdrop-blur-sm rounded-xl border border-gray-700 p-5 hover:border-gray-600 transition">\r
              <div class="flex items-start justify-between mb-3">\r
                <div class="flex items-center gap-3">\r
                  <div [class]="'p-2 rounded-lg ' + \r
                    (notif.tipo === 'email' ? 'bg-blue-600/20' : \r
                     notif.tipo === 'whatsapp' ? 'bg-green-600/20' : 'bg-gray-600/20')">\r
                    <svg class="w-5 h-5" [class.text-blue-400]="notif.tipo === 'email'" \r
                         [class.text-green-400]="notif.tipo === 'whatsapp'" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                      <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/>\r
                    </svg>\r
                  </div>\r
                  <div>\r
                    <p class="text-white font-medium">{{ notif.asunto }}</p>\r
                    <p class="text-gray-500 text-xs">Enviado por {{ notif.enviado_por_nombre }} \u2022 {{ notif.fecha_envio | date:'medium' }}</p>\r
                  </div>\r
                </div>\r
                <span [class]="'px-2 py-1 rounded-full text-xs font-medium ' + \r
                  (notif.estado_envio === 'enviado' ? 'bg-green-900/40 text-green-300' : 'bg-yellow-900/40 text-yellow-300')">\r
                  {{ notif.estado_envio }}\r
                </span>\r
              </div>\r
              <div class="bg-gray-900/50 rounded-lg p-4">\r
                <p class="text-gray-300 text-sm whitespace-pre-wrap">{{ notif.mensaje }}</p>\r
              </div>\r
            </div>\r
          </div>\r
          <ng-template #sinNotificaciones>\r
            <div class="text-center py-12 bg-gray-800/50 rounded-2xl border border-gray-700">\r
              <svg class="w-12 h-12 text-gray-600 mx-auto mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/>\r
              </svg>\r
              <p class="text-gray-500">No se han enviado notificaciones</p>\r
            </div>\r
          </ng-template>\r
        </div>\r
\r
        <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
        <!-- TAB: DOCUMENTOS -->\r
        <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
        <div *ngIf="activeTab === 'documentos'" class="space-y-6">\r
          \r
          <div class="flex justify-between items-center">\r
            <h3 class="text-xl font-bold text-white">Documentos Adjuntos</h3>\r
            <button (click)="showDocumentoModal = true" \r
                    class="flex items-center gap-2 px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition">\r
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/>\r
              </svg>\r
              Subir Documento\r
            </button>\r
          </div>\r
\r
          <!-- Grid de Documentos -->\r
          <div class="grid grid-cols-1 md:grid-cols-2 gap-4" *ngIf="orden.documentos.length > 0; else sinDocumentos">\r
            <div *ngFor="let doc of orden.documentos" \r
                 class="bg-gray-800/50 backdrop-blur-sm rounded-xl border border-gray-700 p-5 hover:border-purple-500/50 transition group">\r
              <div class="flex items-start justify-between mb-3">\r
                <div class="flex items-center gap-3">\r
                  <div class="bg-purple-600/20 p-2.5 rounded-lg">\r
                    <svg class="w-5 h-5 text-purple-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                      <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/>\r
                    </svg>\r
                  </div>\r
                  <div>\r
                    <p class="text-white font-medium group-hover:text-purple-400 transition">{{ doc.nombre }}</p>\r
                    <p class="text-gray-500 text-xs">{{ doc.tipo_documento }} \u2022 {{ doc.fecha_subida | date:'mediumDate' }}</p>\r
                  </div>\r
                </div>\r
              </div>\r
              <div class="flex gap-2">\r
                <a [href]="doc.url_archivo" target="_blank" \r
                   class="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600/20 text-blue-400 rounded-lg text-sm hover:bg-blue-600/30 transition">\r
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"/>\r
                  </svg>\r
                  Abrir\r
                </a>\r
                <span class="text-gray-500 text-xs self-center">Subido por {{ doc.subido_por_nombre }}</span>\r
              </div>\r
            </div>\r
          </div>\r
          <ng-template #sinDocumentos>\r
            <div class="text-center py-12 bg-gray-800/50 rounded-2xl border border-gray-700">\r
              <svg class="w-12 h-12 text-gray-600 mx-auto mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/>\r
              </svg>\r
              <p class="text-gray-500">No hay documentos adjuntos</p>\r
            </div>\r
          </ng-template>\r
        </div>\r
\r
        <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
        <!-- TAB: HISTORIAL DE ESTADOS -->\r
        <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
        <div *ngIf="activeTab === 'historial'" class="space-y-6">\r
          \r
          <h3 class="text-xl font-bold text-white">Historial de Cambios de Estado</h3>\r
\r
          <!-- Timeline -->\r
          <div class="relative" *ngIf="orden.historial_estados.length > 0; else sinHistorial">\r
            <div class="absolute left-4 top-0 bottom-0 w-0.5 bg-gray-700"></div>\r
            \r
            <div class="space-y-6">\r
              <div *ngFor="let hist of orden.historial_estados; let last = last" class="relative pl-12">\r
                <div [class]="'absolute left-2 top-1 w-5 h-5 rounded-full border-2 ' + \r
                  (last ? 'bg-orange-500 border-orange-500' : 'bg-gray-800 border-gray-600')"></div>\r
                \r
                <div class="bg-gray-800/50 backdrop-blur-sm rounded-xl border border-gray-700 p-4">\r
                  <div class="flex items-center justify-between mb-2">\r
                    <div class="flex items-center gap-2">\r
                      <span class="text-gray-400 text-sm">De:</span>\r
                      <span class="text-white font-medium">{{ hist.estado_anterior }}</span>\r
                      <svg class="w-4 h-4 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">\r
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 7l5 5m0 0l-5 5m5-5H6"/>\r
                      </svg>\r
                      <span class="text-gray-400 text-sm">A:</span>\r
                      <span class="text-orange-400 font-medium">{{ hist.estado_nuevo }}</span>\r
                    </div>\r
                    <span class="text-gray-500 text-xs">{{ hist.fecha_cambio | date:'medium' }}</span>\r
                  </div>\r
                  <p class="text-gray-500 text-xs" *ngIf="hist.responsable">\r
                    Realizado por: {{ hist.responsable }}\r
                  </p>\r
                </div>\r
              </div>\r
            </div>\r
          </div>\r
          <ng-template #sinHistorial>\r
            <div class="text-center py-12 bg-gray-800/50 rounded-2xl border border-gray-700">\r
              <p class="text-gray-500">No hay historial de cambios</p>\r
            </div>\r
          </ng-template>\r
        </div>\r
\r
      </div>\r
\r
    </ng-container>\r
\r
  </div>\r
</div>\r
\r
<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r
     MODAL: ENVIAR NOTIFICACI\xD3N\r
\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
<div *ngIf="showNotificarModal" class="fixed inset-0 z-50 flex items-center justify-center p-4" (click)="showNotificarModal = false">\r
  <div class="absolute inset-0 bg-black/70 backdrop-blur-sm"></div>\r
  \r
  <div class="relative bg-gray-900 border border-gray-700 rounded-2xl w-full max-w-lg shadow-2xl" (click)="$event.stopPropagation()">\r
    \r
    <div class="flex items-center justify-between px-6 py-5 border-b border-gray-800">\r
      <h2 class="text-white font-semibold text-lg">Enviar Notificaci\xF3n al Cliente</h2>\r
      <button (click)="showNotificarModal = false" class="text-gray-500 hover:text-white transition p-1 rounded-lg hover:bg-gray-800">\r
        <svg class="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">\r
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>\r
        </svg>\r
      </button>\r
    </div>\r
\r
    <div class="px-6 py-5 space-y-4">\r
      <div>\r
        <label class="block text-sm font-medium text-gray-300 mb-2">Tipo de Notificaci\xF3n</label>\r
        <select [(ngModel)]="notificacion.tipo" class="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white">\r
          <option value="email">Email</option>\r
          <option value="whatsapp">WhatsApp</option>\r
          <option value="sms">SMS</option>\r
        </select>\r
      </div>\r
      \r
      <div>\r
        <label class="block text-sm font-medium text-gray-300 mb-2">Asunto</label>\r
        <input type="text" [(ngModel)]="notificacion.asunto" \r
               class="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white placeholder-gray-500"\r
               placeholder="Asunto de la notificaci\xF3n" />\r
      </div>\r
      \r
      <div>\r
        <label class="block text-sm font-medium text-gray-300 mb-2">Mensaje</label>\r
        <textarea [(ngModel)]="notificacion.mensaje" rows="5"\r
                  class="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white placeholder-gray-500 resize-none"\r
                  placeholder="Escribe el mensaje para el cliente..."></textarea>\r
      </div>\r
    </div>\r
\r
    <div class="px-6 py-4 border-t border-gray-800 flex gap-3">\r
      <button (click)="enviarNotificacion()" [disabled]="enviandoNotificacion"\r
              class="flex-1 flex items-center justify-center gap-2 bg-blue-600 text-white py-2.5 rounded-lg font-medium hover:bg-blue-700 disabled:opacity-60 transition">\r
        <svg *ngIf="enviandoNotificacion" class="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24">\r
          <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"/>\r
          <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"/>\r
        </svg>\r
        {{ enviandoNotificacion ? 'Enviando...' : 'Enviar Notificaci\xF3n' }}\r
      </button>\r
      <button (click)="showNotificarModal = false" [disabled]="enviandoNotificacion"\r
              class="flex-1 py-2.5 text-sm text-gray-300 hover:text-white border border-gray-700 hover:border-gray-500 rounded-lg transition disabled:opacity-60">\r
        Cancelar\r
      </button>\r
    </div>\r
  </div>\r
</div>\r
\r
<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r
     MODAL: REGISTRAR PAGO\r
\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\r
<div *ngIf="showPagoModal" class="fixed inset-0 z-50 flex items-center justify-center p-4" (click)="showPagoModal = false">\r
  <div class="absolute inset-0 bg-black/70 backdrop-blur-sm"></div>\r
  \r
  <div class="relative bg-gray-900 border border-gray-700 rounded-2xl w-full max-w-lg shadow-2xl" (click)="$event.stopPropagation()">\r
    \r
    <div class="flex items-center justify-between px-6 py-5 border-b border-gray-800">\r
      <h2 class="text-white font-semibold text-lg">Registrar Pago Parcial</h2>\r
      <button (click)="showPagoModal = false" class="text-gray-500 hover:text-white transition p-1 rounded-lg hover:bg-gray-800">\r
        <svg class="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">\r
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>\r
        </svg>\r
      </button>\r
    </div>\r
\r
    <div class="px-6 py-5 space-y-4">\r
      <div class="grid grid-cols-2 gap-4">\r
        <div>\r
          <label class="block text-sm font-medium text-gray-300 mb-2">N\xB0 Cuota</label>\r
          <input type="number" [(ngModel)]="pagoParcial.numero_cuota" min="1"\r
                 class="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white" />\r
        </div>\r
        <div>\r
          <label class="block text-sm font-medium text-gray-300 mb-2">Monto ($)</label>\r
          <input type="number" [(ngModel)]="pagoParcial.monto_pagado" min="0" step="0.01"\r
                 class="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white" />\r
        </div>\r
      </div>\r
      \r
      <div>\r
        <label class="block text-sm font-medium text-gray-300 mb-2">Fecha de Pago</label>\r
        <input type="date" [(ngModel)]="pagoParcial.fecha_pago"\r
               class="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white [color-scheme:dark]" />\r
      </div>\r
      \r
      <div>\r
        <label class="block text-sm font-medium text-gray-300 mb-2">URL Comprobante</label>\r
        <input type="text" [(ngModel)]="pagoParcial.comprobante_url"\r
               class="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white placeholder-gray-500"\r
               placeholder="https://..." />\r
      </div>\r
      \r
      <div>\r
        <label class="block text-sm font-medium text-gray-300 mb-2">Notas</label>\r
        <textarea [(ngModel)]="pagoParcial.notas" rows="3"\r
                  class="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white placeholder-gray-500 resize-none"\r
                  placeholder="Notas adicionales..."></textarea>\r
      </div>\r
    </div>\r
\r
    <div class="px-6 py-4 border-t border-gray-800 flex gap-3">\r
      <button (click)="registrarPago()" [disabled]="registrandoPago"\r
              class="flex-1 flex items-center justify-center gap-2 bg-green-600 text-white py-2.5 rounded-lg font-medium hover:bg-green-700 disabled:opacity-60 transition">\r
        <svg *ngIf="registrandoPago" class="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24">\r
          <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"/>\r
          <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"/>\r
        </svg>\r
        {{ registrandoPago ? 'Registrando...' : 'Registrar Pago' }}\r
      </button>\r
      <button (click)="showPagoModal = false" [disabled]="registrandoPago"\r
              class="flex-1 py-2.5 text-sm text-gray-300 hover:text-white border border-gray-700 hover:border-gray-500 rounded-lg transition disabled:opacity-60">\r
        Cancelar\r
      </button>\r
    </div>\r
  </div>\r
</div>` }]
  }], () => [{ type: VentasService2 }, { type: ActivatedRoute }, { type: ChangeDetectorRef }, { type: NgZone }], null);
})();
